export type BenchmarkStatus = "VERIFIED" | "REPRODUCED" | "PENDING";

export const BENCHMARK_STATUS_VALUES: readonly BenchmarkStatus[] = ["VERIFIED", "REPRODUCED", "PENDING"];

export type GpuVendor = "NVIDIA" | "AMD" | "APPLE" | "CPU";

export const GPU_VENDOR_VALUES: readonly GpuVendor[] = ["NVIDIA", "AMD", "APPLE", "CPU"];

export type TimingSource = "provider" | "estimated_from_ttft";

export const TIMING_SOURCE_VALUES: readonly TimingSource[] = ["provider", "estimated_from_ttft"];

/** A single, fully specified inference benchmark run. One file per run in results/{family}/. */
export interface BenchmarkRecord {
  /** Run identifier: RUN-YYYY-MM-DD-HHHHHH. The suffix is a content hash of the run, so concurrent submissions cannot collide and an id cannot be chosen by hand. */
  id: string;
  model: string;
  /** Model family slug; must match the results/ subdirectory. */
  family: string;
  /** Pinned model weights revision (commit hash). */
  modelRevision: string;
  quantization: string;
  hardware: string;
  gpuVendor: GpuVendor;
  /** GB; unified memory on Apple silicon. */
  vram: number;
  ram: number;
  cpu: string;
  engine: string;
  engineVersion: string;
  /** Semantic version of the runner/workload that produced the run. */
  benchmarkVersion: string;
  /** Versioned ReBench evaluation suite identifier. */
  suite: string;
  /** Whether prompt TPS used provider timing metadata or an estimate. */
  timingSource?: TimingSource;
  trials?: { generatedTokens: number; ttft: number; generationMs: number; generationTPS: number }[];
  promptTokens: number;
  generatedTokens: number;
  /** Prompt evaluation throughput, tokens/s. */
  promptTPS: number;
  /** Generation throughput, tokens/s. */
  generationTPS: number;
  /** Time to first token, ms. Must be consistent with promptTokens/promptTPS. */
  ttft: number;
  /** ReBench composite index, see methodology 07. */
  score: number;
  /** GitHub handle of the contributor who produced the run. */
  contributor: string;
  /** ISO-8601 UTC instant of the run. Its date must match the id. */
  timestamp: string;
  gitCommit: string;
  status: BenchmarkStatus;
}

